cat > src/App.tsx <<'EOF'
import { useCallback, useState } from 'react';
import { Button, Card, SegmentedRadioGroup, Text, useLang } from '@gravity-ui/uikit';

import { appI18n, setAppLang } from './i18n';

export function App() {
  const { lang } = useLang();
  const { t } = appI18n.useTranslation();
  const [count, setCount] = useState(0);

  const handleLanguageUpdate = useCallback((value: string) => {
    setAppLang(value === 'ru' ? 'ru' : 'en');
  }, []);

  return (
    <div style={{ padding: 24, maxWidth: 720, margin: '0 auto', display: 'grid', gap: 16 }}>
      <Text variant=\"header-1\">{t('title')}</Text>
      <Text variant=\"body-1\" color=\"secondary\">
        {t('subtitle')}
      </Text>

      <div style={{ display: 'grid', gap: 8 }}>
        <Text variant=\"subheader-2\">{t('language_label')}</Text>
        <SegmentedRadioGroup
          value={lang === 'ru' ? 'ru' : 'en'}
          onUpdate={handleLanguageUpdate}
          options={[
            { value: 'en', content: t('english') },
            { value: 'ru', content: t('russian') },
          ]}
        />
      </div>

      <Card view=\"raised\" style={{ padding: 24, display: 'grid', gap: 12 }}>
        <Text variant=\"header-2\">{t('card_title')}</Text>
        <Text variant=\"body-2\">{t('card_body')}</Text>
        <Button view=\"action\" size=\"l\" onClick={() => setCount((value) => value + 1)}>
          {t('action_button')} {count}
        </Button>
      </Card>

      <Text variant=\"caption-1\" color=\"secondary\">
        {t('note')}
      </Text>
    </div>
  );
}
EOF
